using System;using System.IO;using System.Linq;using System.Text;using System.Drawing;using System.Data;using System.Windows.Forms;using System.Collections.Generic;using System.Web.Script.Serialization;
namespace MuEditorPhoenix {
 public partial class PhoenixEditorForm {
  internal void PreviewProject(string serverPath,string clientPath,string host,string database){server.Text=serverPath;client.Text=clientPath;sqlHost.Text=host;sqlDb.Text=database;integrated.Checked=true;trust.Checked=true;OpenProject();ConnectDatabase();var chars=db.BrowseCharacters("");if(chars.Rows.Count>0)LoadPerson(chars.Rows[0]["AccountID"].ToString(),chars.Rows[0]["Name"].ToString());}
  internal void CaptureV2(string folder){Directory.CreateDirectory(folder);Show();Application.DoEvents();foreach(int page in new[]{1,4,5,6}){tabs.SelectedIndex=page;PerformLayout();Application.DoEvents();using(var image=new Bitmap(Width,Height)){DrawToBitmap(image,new Rectangle(0,0,Width,Height));image.Save(Path.Combine(folder,"page-"+page+"-pt.png"));}}Words.Language="en";ApplyLanguage(this);tabs.SelectedIndex=5;Application.DoEvents();using(var image=new Bitmap(Width,Height)){DrawToBitmap(image,new Rectangle(0,0,Width,Height));image.Save(Path.Combine(folder,"inventory-en.png"));}Words.Language="es";ApplyLanguage(this);tabs.SelectedIndex=4;Application.DoEvents();using(var image=new Bitmap(Width,Height)){DrawToBitmap(image,new Rectangle(0,0,Width,Height));image.Save(Path.Combine(folder,"people-es.png"));}Close();}
  internal bool SessionFieldsMatch(SessionSettings expected){return sqlHost.Text==expected.SqlHost&&sqlDb.Text==expected.SqlDatabase&&sqlUser.Text==expected.SqlUser&&sqlPassword.Text==expected.ReadSecret()&&rememberPassword.Checked==expected.RememberPassword&&autoConnect.Checked==expected.AutoConnect;}
  internal object ProbeSession(){ShowInTaskbar=false;StartPosition=FormStartPosition.Manual;Location=new Point(-32000,-32000);Show();Application.DoEvents();var result=new{connected=db.Connected,accounts=accountsGrid.Rows.Count,characters=charactersGrid.Rows.Count,projectRestored=catalog.Items.Count>0,sqlFieldsRestored=!string.IsNullOrEmpty(sqlHost.Text)&&!string.IsNullOrEmpty(sqlDb.Text),page=tabs.SelectedIndex};Close();return result;}
 }
 public static class V2Tests {
  static void Check(bool condition,string label){if(!condition)throw new Exception("FAIL: "+label);}
  static void Reject(Action action,string label){bool rejected=false;try{action();}catch{rejected=true;}Check(rejected,label);}
  public static int SessionProbe(string report,string root){Guard.LocalData=root;Application.EnableVisualStyles();using(var form=new PhoenixEditorForm()){File.WriteAllText(report,new JavaScriptSerializer().Serialize(form.ProbeSession()));}return 0;}
  public static int Run(string report,string server,string client,string host,string database){string previous=Guard.LocalData;string temp=Path.Combine(Path.GetTempPath(),"MuEditorPhoenix-V2-test-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(temp);Guard.LocalData=temp;
   try{var settings=new SessionSettings{Server="synthetic",SqlHost="sql-test.invalid",SqlDatabase="SyntheticDB",SqlUser="synthetic",RememberPassword=true,AutoConnect=true,Language="pt"};settings.RememberSecret("synthetic-not-a-real-password");settings.Save();string text=File.ReadAllText(SessionSettings.FilePath);Check(!text.Contains("synthetic-not-a-real-password"),"password not plaintext");var loaded=SessionSettings.Load();Check(loaded.ReadSecret()=="synthetic-not-a-real-password"&&loaded.AutoConnect,"session round trip");using(var form=new PhoenixEditorForm()){Check(form.SessionFieldsMatch(loaded),"connection fields restored into form");}loaded.RememberPassword=false;loaded.RememberSecret("unused");Check(loaded.PasswordCipher==""&&loaded.ReadSecret()=="","forget password");
    var catalog=new Catalog();string itemPath=Path.Combine(temp,"Item.xml");File.WriteAllText(itemPath,"<ItemList><Section Index='0'><Item Index='1' Width='2' Height='2' Name='Synthetic Sword' DW='1'/></Section></ItemList>");catalog.Load(itemPath);Check(catalog.Items[1].Attributes["DW"]=="1","catalog class filter metadata");byte[] bytes=Enumerable.Repeat((byte)255,5975).ToArray();var inventory=new ItemBuffer(bytes);var warehouse=new ItemBuffer(Enumerable.Repeat((byte)255,6000).ToArray());byte[] item=Enumerable.Range(0,25).Select(i=>(byte)i).ToArray();item[0]=1;item[7]=0;item[9]=0;inventory.Set(12,item);ItemBuffer.Move(inventory,12,warehouse,0,catalog,0,120);Check(inventory.Empty(12)&&warehouse.Get(0).SequenceEqual(item),"cross buffer transfer preserves serial and modern fields");Reject(()=>ItemBuffer.Move(warehouse,0,inventory,19,catalog,12,76),"right boundary");inventory.Set(13,item);Reject(()=>ItemBuffer.Move(warehouse,0,inventory,12,catalog,12,76),"overlap");Check(!warehouse.Empty(0),"failed transfer leaves source intact");Reject(()=>ItemBuffer.Move(warehouse,0,inventory,75,catalog,12,76),"bottom boundary");
    Words.Language="en";Check(Words.T("Inventário e baú")=="Inventory & warehouse","English");Words.Language="es";Check(Words.T("Inventário e baú")=="Inventario y baúl","Spanish");Check(Words.Source("Inventory & warehouse")=="Inventário e baú","language roundtrip");Words.Language="pt";
    var evidence=new List<string>{"encrypted password persistence","connection restored into form","forget password","class filter metadata","inventory/warehouse transfer preserves every byte","failed moves do not alter source","English/Spanish/Portuguese resources"};
    if(server!=null){new SessionSettings().Save();Application.EnableVisualStyles();using(var form=new PhoenixEditorForm()){form.PreviewProject(server,client,host,database);form.CaptureV2(Path.Combine(Path.GetDirectoryName(report),"v2-previews"));}evidence.Add("real project read-only UI render: catalog, account/character, inventory, warehouse, preferences");}
    File.WriteAllText(report,new JavaScriptSerializer().Serialize(new{status="PASS",tests=evidence,productionWrites=false}));Console.WriteLine("PASS: V2 persistence, storage, language and UI tests");return 0;
   }finally{Guard.LocalData=previous;Words.Language="pt";}
  }
 }
}
